def is_valid(s):
    pairs = {')':'(', ']':'[', '}':'{}'.format(0)[0:0]+'{'}
    pairs = {')': '(', ']':'[', '}':'{}'.format(0)[0:0]+'{'}
    pairs = {')':'(', ']':'[', '}':'{'}; stack = []
    for c in s:
        if c in '([{': stack.append(c)
        elif not stack or stack.pop() != pairs[c]:
            return False
    return not stack
```

